def test_internal_buy_retry_replaces_source_reservation_without_double_counting() -> None:
    settings = Settings(database_url="sqlite:///:memory:", runtime_mode="paper")
    engine = create_db_engine(settings)
    Base.metadata.create_all(engine)
    session_factory = create_session_factory(engine)
    snapshot = BrokerAccountSnapshot(
        available_cash=Decimal("150.00"),
        buying_power=Decimal("150.00"),
        observed_at=datetime.now(UTC),
        source="stub:retry-capital-reservation",
    )
    with session_factory() as session:
        source_order = BrokerOrder(
            broker_name="kis",
            mode="paper",
            idempotency_key="retry-buy-source",
            symbol="005930",
            side="buy",
            status="retry_pending",
            quantity=1,
            venue="kis",
            asset_class="stock",
            limit_price=Decimal("100.00"),
            request_metadata={
                "exchange": "KRX",
                "execution_scope": _test_kis_execution_scope(
                    settings,
                    venue="kis",
                ),
            },
        )
        session.add(source_order)
        session.commit()
        command = PlaceOrderRequest(
            idempotency_key="retry-buy-child",
            symbol="005930",
            side="buy",
            quantity=1,
            order_type="limit",
            limit_price=Decimal("100.00"),
            time_in_force="day",
            exchange="KRX",
            metadata={
                "retry": {
                    "source": "rejected_order_retry",
                    "source_broker_order_pk": source_order.id,
                }
            },
        )

        trusted_notional, trusted_unknown, trusted_indeterminate = (
            broker_orders_service._local_unmatched_buy_reservation(
                settings=settings,
                db=session,
                adapter=StubBrokerAdapter(
                    config=BrokerConfig(
                        provider="kis",
                        mode="paper",
                        configured=True,
                        api_base_url=KIS_PAPER_API_BASE_URL,
                    )
                ),
                command=command,
                snapshot=snapshot,
                request_source="execution-job:retry-buy-job",
                execution_scope=_test_kis_execution_scope(settings, venue="kis"),
            )
        )
        untrusted_notional, untrusted_unknown, untrusted_indeterminate = (
            broker_orders_service._local_unmatched_buy_reservation(
                settings=settings,
                db=session,
                adapter=StubBrokerAdapter(
                    config=BrokerConfig(
                        provider="kis",
                        mode="paper",
                        configured=True,
                        api_base_url=KIS_PAPER_API_BASE_URL,
                    )
                ),
                command=command,
                snapshot=snapshot,
                request_source="post:/orders",
                execution_scope=_test_kis_execution_scope(settings, venue="kis"),
            )
        )

        assert (trusted_notional, trusted_unknown) == (Decimal("0"), 0)
        assert (untrusted_notional, untrusted_unknown) == (Decimal("100.00"), 0)
        assert trusted_indeterminate is None
        assert untrusted_indeterminate is None
        assert broker_orders_service._buy_capital_reservation_decision(
            settings=settings,
            snapshot=snapshot,
            command=command,
            plan_item=None,
            local_open_buy_notional=trusted_notional,
            local_open_buy_unknown_count=trusted_unknown,
            observed_at=datetime.now(UTC),
        ) is None
        untrusted_decision = broker_orders_service._buy_capital_reservation_decision(
            settings=settings,
            snapshot=snapshot,
            command=command,
            plan_item=None,
            local_open_buy_notional=untrusted_notional,
            local_open_buy_unknown_count=untrusted_unknown,
            observed_at=datetime.now(UTC),
        )
        assert untrusted_decision is not None
        assert untrusted_decision.gate_name == "buy_capital_reservation"
    engine.dispose()


def test_concurrent_buy_intents_share_one_account_capital_reservation(tmp_path) -> None:
    snapshot_entered = Event()
    release_snapshot = Event()

    class BlockingSnapshotAdapter(StubBrokerAdapter):
        def __init__(self) -> None:
            super().__init__(
                config=BrokerConfig(
                    provider="kis",
                    mode="paper",
                    configured=True,
                    api_base_url=KIS_PAPER_API_BASE_URL,
                ),
                token_grant=build_token_grant(),
                order_placement=build_order_placement(broker_order_id="concurrent-buy-1"),
                account_snapshot=BrokerAccountSnapshot(
                    available_cash=Decimal("15.00"),
                    buying_power=Decimal("15.00"),
                    observed_at=datetime.now(UTC),
                    source="stub:concurrent-capital",
                    total_asset_value=Decimal("1000.00"),
                    previous_total_asset_value=Decimal("1000.00"),
                    asset_change_amount=Decimal("0"),
                    unrealized_pnl=Decimal("0"),
                ),
            )
            self.snapshot_calls = 0

        def get_account_snapshot(
            self,
            access_token: str,
            **kwargs: object,
        ) -> BrokerAccountSnapshot:
            self.snapshot_calls += 1
            if self.snapshot_calls == 1:
                snapshot_entered.set()
                assert release_snapshot.wait(timeout=2)
            return super().get_account_snapshot(access_token, **kwargs)

    database_url = f"sqlite:///{tmp_path / 'concurrent-order-intents.db'}"
    settings = Settings(
        database_url=database_url,
        runtime_mode="paper",
        kis_app_key="paper-key",
        kis_app_secret="paper-secret",
        kis_account_number="12345678",
    )
    adapter = BlockingSnapshotAdapter()
    app, engine = build_test_app(settings=settings, broker_adapter=adapter)
    client = TestClient(app)
    assert client.post(
        "/controls/resume",
        json={"actor": "ops", "source": "test", "reason": "concurrency regression"},
    ).status_code == 200
    results: dict[str, object] = {}
    errors: list[BaseException] = []

    def submit(key: str, symbol: str) -> None:
        try:
            with app.state.db_session_factory() as session:
                results[key] = broker_orders_service.place_broker_order(
                    settings=settings,
                    db=session,
                    adapter=adapter,
                    command=PlaceOrderRequest(
                        idempotency_key=key,
                        symbol=symbol,
                        side="buy",
                        quantity=1,
                        order_type="limit",
                        limit_price=Decimal("10.00"),
                        time_in_force="day",
                        exchange="KRX",
                    ),
                )
        except BaseException as exc:  # pragma: no cover - asserted below
            errors.append(exc)

    first = Thread(target=submit, args=("concurrent-buy-a", "005930"))
    second = Thread(target=submit, args=("concurrent-buy-b", "000660"))
    first.start()
    assert snapshot_entered.wait(timeout=2)
    second.start()
    time.sleep(0.05)
    assert adapter.snapshot_calls == 1
    release_snapshot.set()
    first.join(timeout=3)
    second.join(timeout=3)

    assert errors == []
    assert not first.is_alive()
    assert not second.is_alive()
    assert sorted(result.status_code for result in results.values()) == [201, 409]
    assert len(adapter.order_calls) == 1
    blocked = next(result for result in results.values() if result.status_code == 409)
    assert blocked.payload["order"]["last_error_code"] == "buy_capital_reservation"
    engine.dispose()


@pytest.mark.parametrize("control_path", ["/controls/pause", "/controls/kill-switch"])
def test_order_submission_rechecks_runtime_control_after_account_snapshot(
    tmp_path,
    control_path: str,
) -> None:
    snapshot_entered = Event()
    release_snapshot = Event()

    class BlockingSnapshotAdapter(StubBrokerAdapter):
        def get_account_snapshot(
            self,
            access_token: str,
            **kwargs: object,
        ) -> BrokerAccountSnapshot:
            snapshot_entered.set()
            assert release_snapshot.wait(timeout=2)
            return super().get_account_snapshot(access_token, **kwargs)

    settings = Settings(
        database_url=f"sqlite:///{tmp_path / 'runtime-fence-order.db'}",
        runtime_mode="paper",
        kis_app_key="paper-key",
        kis_app_secret="paper-secret",
        kis_account_number="12345678",
    )
    broker_adapter = BlockingSnapshotAdapter(
        config=BrokerConfig(
            provider="kis",
            mode="paper",
            configured=True,
            api_base_url=KIS_PAPER_API_BASE_URL,
        ),
        token_grant=build_token_grant(),
        order_placement=build_order_placement(),
            account_snapshot=BrokerAccountSnapshot(
                available_cash=Decimal("1000.00"),
                buying_power=Decimal("1000.00"),
                observed_at=datetime.now(UTC),
                source="stub:runtime-fence",
                total_asset_value=Decimal("10000.00"),
                previous_total_asset_value=Decimal("10000.00"),
                asset_change_amount=Decimal("0.00"),
                unrealized_pnl=Decimal("0.00"),
            ),
    )
    app, engine = build_test_app(settings=settings, broker_adapter=broker_adapter)
    client = TestClient(app)
    assert client.post(
        "/controls/resume",
        json={"actor": "ops", "source": "test", "reason": "enable order"},
    ).status_code == 200
    result: dict[str, object] = {}
    command = PlaceOrderRequest(
        idempotency_key=f"runtime-fence-{control_path.rsplit('/', 1)[-1]}",
        symbol="005930",
        side="buy",
        quantity=1,
        order_type="limit",
        limit_price=Decimal("100.00"),
        time_in_force="day",
        exchange="KRX",
    )

    def submit() -> None:
        with app.state.db_session_factory() as session:
            result["value"] = broker_orders_service.place_broker_order(
                settings=settings,
                db=session,
                adapter=broker_adapter,
                command=command,
            )

    thread = Thread(target=submit)
    thread.start()
    assert snapshot_entered.wait(timeout=2)
    control = client.post(
        control_path,
        json={"actor": "ops", "source": "test", "reason": "stop in-flight order"},
    )
    assert control.status_code == 200
    release_snapshot.set()
    thread.join(timeout=3)

    assert not thread.is_alive()
    placement = result["value"]
    assert isinstance(placement, broker_orders_service.PlaceBrokerOrderResult)
    assert placement.status_code == 409
    assert placement.payload["block_reason"] in {"paused", "kill_switch"}
    assert broker_adapter.order_calls == []
    with app.state.db_session_factory() as session:
        order = session.scalar(
            select(BrokerOrder).where(
                BrokerOrder.idempotency_key
                == f"runtime-fence-{control_path.rsplit('/', 1)[-1]}"
            )
        )
        assert order is not None
        assert order.status == "rejected"
        assert order.last_error_classification == "runtime_safety_control"
        assert order.last_error_code == placement.payload["block_reason"]
        assert order.request_metadata["broker_account_scope"] == {
            "policy_version": 1,
            "scope": broker_orders_service._account_drawdown_recovery_scope(
                settings=settings,
                provider="kis",
                asset_class="stock",
                exchange="KRX",
            ),
        }
        assert any(event.event_type == "submission_blocked" for event in order.events)
    if control_path == "/controls/pause":
        assert client.post(
            "/controls/resume",
            json={"actor": "ops", "source": "test", "reason": "resume fenced order"},
        ).status_code == 200
        with app.state.db_session_factory() as session:
            changed_request = broker_orders_service.place_broker_order(
                settings=settings,
                db=session,
                adapter=broker_adapter,
                command=command.model_copy(update={"quantity": 2}),
            )
        assert changed_request.status_code == 200
        assert changed_request.payload["duplicate"] is True
        assert broker_adapter.order_calls == []
        with app.state.db_session_factory() as session:
            resumed = broker_orders_service.place_broker_order(
                settings=settings,
                db=session,
                adapter=broker_adapter,
                command=command,
            )
        assert resumed.status_code == 201
        assert len(broker_adapter.order_calls) == 1
        with app.state.db_session_factory() as session:
            duplicate = broker_orders_service.place_broker_order(
                settings=settings,
                db=session,
                adapter=broker_adapter,
                command=command,
            )
        assert duplicate.status_code == 200
        assert duplicate.payload["duplicate"] is True
        assert len(broker_adapter.order_calls) == 1
    engine.dispose()


def test_runtime_fenced_recovery_child_cannot_cross_kis_account_scope() -> None:
    account_a = Settings(
        database_url="sqlite:///:memory:",
        runtime_mode="paper",
        kis_app_key="paper-key",
        kis_app_secret="paper-secret",
        kis_account_number="11112222",
        account_drawdown_recovery_scope_secret="stable-scope-secret",
        account_drawdown_gate_enabled=False,
    )
    account_b = account_a.model_copy(update={"kis_account_number": "99990000"})
    account_a_scope = broker_orders_service._account_drawdown_recovery_scope(
        settings=account_a,
        provider="kis",
        asset_class="stock",
        exchange="KRX",
    )
    account_b_scope = broker_orders_service._account_drawdown_recovery_scope(
        settings=account_b,
        provider="kis",
        asset_class="stock",
        exchange="KRX",
    )
    assert account_a_scope != account_b_scope
    command = PlaceOrderRequest(
        idempotency_key="execution-job:account-a:recovery:1",
        provider="kis",
        asset_class="stock",
        symbol="005930",
        side="buy",
        quantity=1,
        order_type="limit",
        limit_price=Decimal("100000"),
        time_in_force="day",
        exchange="KRX",
        metadata={
            "account_drawdown_recovery": {
                "policy_version": 1,
                "recovery_scope": account_a_scope,
                "source_broker_order_pk": "account-a-source",
                "source_idempotency_key": "execution-job:account-a",
                "recovery_generation": 1,
            }
        },
    )
    account_b_adapter = StubBrokerAdapter(
        config=BrokerConfig(
            provider="kis",
            mode="paper",
            configured=True,
            api_base_url=KIS_PAPER_API_BASE_URL,
        ),
        token_grant=build_token_grant(),
        order_placement=build_order_placement(
            broker_order_id="must-not-submit-account-a-child-on-account-b"
        ),
    )
    account_a_adapter = StubBrokerAdapter(
        config=BrokerConfig(
            provider="kis",
            mode="paper",
            configured=True,
            api_base_url=KIS_PAPER_API_BASE_URL,
        ),
        token_grant=build_token_grant(),
        order_placement=build_order_placement(
            broker_order_id="same-account-fenced-child-retry"
        ),
    )
    app, engine = build_test_app(
        settings=account_b,
        broker_adapter=account_b_adapter,
    )
    client = TestClient(app)
    assert client.post(
        "/controls/resume",
        json={"actor": "ops", "source": "test", "reason": "enable retries"},
    ).status_code == 200

    with app.state.db_session_factory() as session:
        session.add(
            BrokerOrder(
                broker_name="kis",
                execution_plan_item_id=None,
                mode="paper",
                idempotency_key=command.idempotency_key,
                symbol=command.symbol,
                side="buy",
                status="rejected",
                quantity=command.quantity,
                asset_class=command.asset_class,
                limit_price=command.limit_price,
                request_metadata={
                    "original_command": (
                        broker_orders_service._order_command_payload(command)
                    ),
                    "broker_account_scope": {
                        "policy_version": 1,
                        "scope": account_a_scope,
                    },
                    "runtime_safety_fence": {
                        "block_reason": "paused",
                        "broker_call_started": False,
                    },
                },
                response_metadata={"runtime_safety_fence": {"paused": True}},
                last_error_classification="runtime_safety_control",
                last_error_code="paused",
                last_error_retryable=True,
            )
        )
        session.commit()

    with app.state.db_session_factory() as session:
        foreign_retry = broker_orders_service.place_broker_order(
            settings=account_b,
            db=session,
            adapter=account_b_adapter,
            command=command,
            request_source="execution-job:next_open_buy",
        )

    assert foreign_retry.status_code == 200
    assert foreign_retry.payload["duplicate"] is True
    assert account_b_adapter.order_calls == []

    with app.state.db_session_factory() as session:
        same_account_retry = broker_orders_service.place_broker_order(
            settings=account_a,
            db=session,
            adapter=account_a_adapter,
            command=command,
            request_source="execution-job:next_open_buy",
        )

    assert same_account_retry.status_code == 201
    assert len(account_a_adapter.order_calls) == 1
    engine.dispose()


def test_automated_buy_rechecks_hourly_risk_off_after_account_snapshot(
    tmp_path,
) -> None:
    snapshot_entered = Event()
    release_snapshot = Event()

    class BlockingSnapshotAdapter(StubBrokerAdapter):
        def get_account_snapshot(
            self,
            access_token: str,
            **kwargs: object,
        ) -> BrokerAccountSnapshot:
            snapshot_entered.set()
            assert release_snapshot.wait(timeout=2)
            return super().get_account_snapshot(access_token, **kwargs)

    settings = Settings(
        database_url=f"sqlite:///{tmp_path / 'hourly-risk-off-order-race.db'}",
        runtime_mode="paper",
        kis_app_key="paper-key",
        kis_app_secret="paper-secret",
        kis_account_number="12345678",
    )
    broker_adapter = BlockingSnapshotAdapter(
        config=BrokerConfig(
            provider="kis",
            mode="paper",
            configured=True,
            api_base_url=KIS_PAPER_API_BASE_URL,
        ),
        token_grant=build_token_grant(),
        order_placement=build_order_placement(),
        account_snapshot=BrokerAccountSnapshot(
            available_cash=Decimal("1000000.00"),
            buying_power=Decimal("1000000.00"),
            observed_at=datetime.now(UTC),
            source="stub:hourly-risk-off-order-race",
            total_asset_value=Decimal("10000000.00"),
            previous_total_asset_value=Decimal("10000000.00"),
            asset_change_amount=Decimal("0.00"),
            unrealized_pnl=Decimal("0.00"),
        ),
    )
    app, engine = build_test_app(settings=settings, broker_adapter=broker_adapter)
    client = TestClient(app)
    assert client.post(
        "/controls/resume",
        json={"actor": "ops", "source": "test", "reason": "enable order"},
    ).status_code == 200
    item_id = _create_watch_buy_candidate(
        client,
        plan_id="plan-hourly-risk-off-order-race",
        trigger_price="100.00",
        chase_limit_price="110.00",
        risk_context={
            "exchange": "KRX",
            "stop_price": "90.00",
            "trigger_direction": "at_or_above",
        },
    )
    result: dict[str, object] = {}
    errors: list[BaseException] = []
    command = PlaceOrderRequest(
        idempotency_key=f"monitoring:watch_buy:{item_id}",
        execution_plan_item_id=item_id,
        provider="kis",
        asset_class="stock",
        symbol="005930",
        side="buy",
        quantity=2,
        order_type="limit",
        limit_price=Decimal("100.00"),
        time_in_force="day",
        exchange="KRX",
    )

    def submit() -> None:
        try:
            with app.state.db_session_factory() as session:
                result["value"] = broker_orders_service.place_broker_order(
                    settings=settings,
                    db=session,
                    adapter=broker_adapter,
                    command=command,
                    request_source="monitoring:intraday_target_stop_monitor",
                )
        except BaseException as exc:  # pragma: no cover - asserted below
            errors.append(exc)

    thread = Thread(target=submit)
    thread.start()
    assert snapshot_entered.wait(timeout=2)
    try:
        risk_off = client.post(
            "/runtime/plan-judgment/action",
            json={
                "risk_flags": 3,
                "risk_reasons": ["severe risk appeared during buy preparation"],
            },
        )
        assert risk_off.status_code == 200
        assert risk_off.json()["action"] == "risk_off_expire"
        with app.state.db_session_factory() as session:
            fenced_item = session.get(ExecutionPlanItem, item_id)
            assert fenced_item is not None
            assert fenced_item.status == "watch_expired"
            assert fenced_item.risk_context["hourly_plan_action"]["action"] == (
                "risk_off_expire"
            )
    finally:
        release_snapshot.set()
    thread.join(timeout=3)

    assert errors == []
    assert not thread.is_alive()
    placement = result["value"]
    assert isinstance(placement, broker_orders_service.PlaceBrokerOrderResult)
    assert (placement.status_code, len(broker_adapter.order_calls)) == (409, 0)
    assert placement.payload["block_reason"] == "hourly_plan_risk_off"
    engine.dispose()


def test_order_intent_lock_scope_does_not_use_enumerable_kis_account_hash() -> None:
    command = PlaceOrderRequest(
        idempotency_key="opaque-order-intent-lock",
        provider="kis",
        venue="krx",
        asset_class="stock",
        symbol="005930",
        side="buy",
        quantity=1,
        order_type="limit",
        limit_price=Decimal("71000"),
        time_in_force="day",
        exchange="KRX",
    )
    base = Settings(
        runtime_mode="live",
        kis_account_number="12345678",
        kis_account_product_code="01",
        account_drawdown_recovery_scope_secret=(
            "stable-order-lock-scope-secret-32-bytes"
        ),
    )
    rotated_key = base.model_copy(
        update={
            "account_drawdown_recovery_scope_secret": (
                "different-order-lock-secret-32-bytes"
            )
        }
    )

    first = broker_orders_service._order_intent_scope_key(
        settings=base,
        adapter=SimpleNamespace(provider="kis"),
        command=command,
    )
    second = broker_orders_service._order_intent_scope_key(
        settings=rotated_key,
        adapter=SimpleNamespace(provider="kis"),
        command=command,
    )

    enumerable = sha256(b"12345678").hexdigest()[:16]
    assert enumerable not in first
    assert first != second
    assert "12345678" not in first


def test_live_alpaca_pre_auth_order_lock_survives_api_key_rotation() -> None:
    command = PlaceOrderRequest(
        idempotency_key="alpaca-pre-auth-lock",
        provider="alpaca",
        venue="alpaca",
        asset_class="crypto",
        symbol="BTC/USD",
        side="buy",
        quote_notional=Decimal("25"),
        order_type="market",
        time_in_force="gtc",
        exchange="ALPACA",
    )
