    new_scope = broker_orders_service._order_intent_scope_key(
        settings=after,
        adapter=SimpleNamespace(provider="alpaca"),
        command=command,
    )

    assert old_scope == new_scope
    assert "old-api-key" not in old_scope
    assert "new-api-key" not in new_scope


