    assert retry_payload["submitted_order_count"] == 1
    assert retry_payload["items"][0]["outcome"] == "submitted"
    assert retry_payload["items"][0]["status"] == "watch_buy_submitted"
    assert len(broker_adapter.order_calls) == 1

    engine.dispose()


