    response = client.post(
        "/monitoring/evaluate",
        json={
            "actor": "ops",
            "source": "test",
            "reason": "protect positive position on its second KRX session",
            "observed_at": "2026-10-06T01:00:00Z",
            "prices": [{"symbol": "005930", "price": "100500.00"}],
        },
    )

    assert response.status_code == 200
