            plan_item_index=0,
            symbol="005930",
            side="buy",
            intent="intraday_watch_buy",
            status="watch_monitoring_active",
            provider="kis",
            asset_class="stock",
            trigger_price=Decimal("71000"),
            limit_price=Decimal("71200"),
            time_in_force="day",
            quantity_policy=quantity_policy,
            risk_context=risk_context,
